deps = {"harvest": [], "index": ["harvest"], "verify": ["index"], "publish": ["verify", "index"]}
order, ready = [], [t for t in deps if not deps[t]]
while ready:
    t = ready.pop(0); order.append(t)
    for x, ds in deps.items():
        if t in ds:
            ds.remove(t)
            if not ds: ready.append(x)
print("Execution order:", order)
assert order.index("harvest") < order.index("index") < order.index("publish")
print("Dependencies respected: OK")

graph = {"a": ["b"], "b": ["c"], "c": ["a"], "d": ["a"]}
color, cycle = {}, []
def dfs(n, path):
    color[n] = "gray"
    for m in graph.get(n, []):
        if color.get(m) == "gray":
            cycle.extend(path[path.index(m):] + [m]); return True
        if color.get(m) is None and dfs(m, path + [m]): return True
    color[n] = "black"; return False
for n in graph:
    if color.get(n) is None and dfs(n, [n]): break
print("Cycle found:" , " -> ".join(cycle) if cycle else "none")

import collections
deps = {"a": [], "b": [], "c": ["a"], "d": ["a", "b"], "e": ["d"]}
done, frontier = set(), collections.deque([t for t in deps if not deps[t]])
waves = []
while frontier:
    wave = list(frontier); frontier.clear(); waves.append(wave)
    done.update(wave)
    for t, ds in deps.items():
        if t not in done and all(d in done for d in ds) and t not in frontier:
            frontier.append(t)
print("Parallel waves:", waves)
assert len(waves) == 3

import collections
CAP = 3
stage_q = collections.deque()
produced, dropped, consumed = 0, 0, 0
for i in range(10):
    if len(stage_q) < CAP:
        stage_q.append(i); produced += 1
    else:
        dropped += 1  # backpressure: producer waits / sheds
    if i % 2 == 0 and stage_q:
        stage_q.popleft(); consumed += 1
print(f"produced={produced} dropped={dropped} consumed={consumed} queued={len(stage_q)}")
assert len(stage_q) <= CAP

cache = {"q:planets": (["Mars", "Venus"], "2026-10-18")}
def answer(q, backend_ok):
    if backend_ok: return (["Mars", "Venus", "Earth"], "live")
    hit = cache.get("q:" + q)
    if hit: return hit[0], "stale-cache " + hit[1]
    return (["Archive temporarily degraded"], "static-fallback")
print(answer("planets", True))
print(answer("planets", False))
